import streamlit as st
import streamlit.components.v1 as components
import json, pathlib
st.set_page_config(page_title='송파구 착한가격업소 지도',layout='wide')
st.title('송파구 착한가격업소 지도')
st.caption('서울시 착한가격업소 현황 제공 파일 기준 · 좌표 출처: 소상공인시장진흥공단 상가(상권)정보(제공 파일). 마커는 건물 기준 위치이며 실제 출입구·가격·영업 여부는 방문 전 확인해 주세요.')
shops=json.loads((pathlib.Path(__file__).parent/'shops.json').read_text(encoding='utf-8'))
def secret(name):
    try:
        return str(st.secrets.get(name, '')).strip()
    except Exception:
        return ''

key = secret('KAKAO_JS_KEY')
# Coordinates are prepared offline from an authorized source.
missing = sum(s.get('lat') is None or s.get('lng') is None for s in shops)
if missing:
    st.caption(f'위치 미등록 {missing}개 업소 · 업소 목록과 품목 검색은 이용 가능합니다.')
# Embed the source records as JSON, escaping HTML script termination.
data=json.dumps(shops,ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}body{font-family:system-ui,sans-serif;margin:0;color:#17352c;background:white}header{display:flex;flex-wrap:wrap;gap:8px;align-items:end;padding:10px 0}label{display:flex;flex-direction:column;font-size:13px;gap:4px;flex:1;min-width:130px}input,select,button{font:inherit;padding:9px;border:1px solid #aabbb4;border-radius:8px;background:white;color:#17352c}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #167c5b}#map{height:390px;background:#edf2ef;border-radius:12px}#status{font-size:13px;padding:8px 0}#list{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:8px;max-height:490px;overflow:auto}.shop{border:1px solid #ccd9d1;border-radius:12px;padding:13px;line-height:1.5}.shop h3{margin:0;font-size:17px}.address{font-size:13px;color:#52645a}.item{display:flex;justify-content:space-between;gap:10px;padding:4px 0}.matched{font-weight:700;color:#17694d}a{color:#17694d}#detail{padding:8px 0}@media(max-width:600px){#map{height:300px;width:86%;margin-inline:auto}header{gap:5px}#list{max-height:400px}}</style></head><body>
<header><label>업소명·주소·품목<input id="q" placeholder="예: 짜장면, 풍납동"></label><label>업종<select id="type"></select></label><label>품목<select id="item"></select></label><label>가격 상한(원)<input id="max" type="number" min="0" step="500" placeholder="제한 없음"></label><label>정렬<select id="sort"><option value="name">업소명 순</option><option value="price">해당 품목 가격 낮은 순</option></select></label><button id="reset">초기화</button><button id="loc">내 위치</button></header><div id="map" role="region" aria-label="착한가격업소 지도"></div><div id="status" role="status"></div><div id="detail" aria-live="polite"></div><div id="list" aria-label="검색 결과"></div>
<script>const shops=__DATA__;const key=__KEY__;const el=id=>document.getElementById(id);let map=null,markers=[],positions=new Map(),filtered=[],done=false;let failed=shops.filter(s=>!Number.isFinite(s.lat)||!Number.isFinite(s.lng)).length;const norm=s=>String(s??'').toLowerCase().replace(/\\s/g,'').replace(/자장면/g,'짜장면').replace(/돈까스/g,'돈가스');function options(id,values){el(id).replaceChildren(new Option('전체',''),...values.sort((a,b)=>a.localeCompare(b,'ko')).map(x=>new Option(x,x)))}options('type',[...new Set(shops.map(s=>s.type))]);function itemOptions(){let old=el('item').value;options('item',[...new Set(shops.filter(s=>!el('type').value||s.type===el('type').value).flatMap(s=>s.items.map(m=>m.category)))]);if([...el('item').options].some(o=>o.value===old))el('item').value=old}itemOptions();function node(tag,text,cls){let n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n}function card(s,matched){let d=node('article','','shop');d.append(node('h3',s.name),node('div',s.type+' · '+s.address,'address'));for(let m of s.items){let r=node('div','','item'+(matched.includes(m)?' matched':''));r.append(node('span',m.name),node('span',m.price==null?'가격 미등록':m.price.toLocaleString('ko-KR')+'원'));d.append(r)}if(s.coordinate_match==='주소 기준 건물 위치')d.append(node('div','주소 기준 건물 위치 · 상호 미대조','address'));if(s.coordinate_match==='미확인')d.append(node('div','지도 위치 미확인','address'));let a=node('a','카카오맵 길찾기');a.target='_blank';a.rel='noopener noreferrer';let p=positions.get(s.id);a.href=p?'https://map.kakao.com/link/to/'+encodeURIComponent(s.name)+','+p.getLat()+','+p.getLng():'https://map.kakao.com/?q='+encodeURIComponent(s.address);d.append(a);if(p&&map){let b=node('button','지도 위치');b.style.marginLeft='8px';b.onclick=()=>{map.setCenter(p);map.setLevel(3);show(s,matched)};d.append(b)}return d}function show(s,m){el('detail').replaceChildren(card(s,m))}function render(){let q=norm(el('q').value),t=el('type').value,c=el('item').value,max=el('max').value===''?Infinity:Number(el('max').value);filtered=shops.filter(s=>!t||s.type===t).map(s=>({s,m:s.items.filter(m=>(!c||m.category===c)&&(max===Infinity||(m.price!==null&&m.price<=max))&&(!q||[s.name,s.address,s.type,m.name,m.category].some(x=>norm(x).includes(q))))})).filter(x=>x.m.length);filtered.sort((a,b)=>el('sort').value==='price'?Math.min(...a.m.map(m=>m.price??Infinity))-Math.min(...b.m.map(m=>m.price??Infinity)):a.s.name.localeCompare(b.s.name,'ko'));el('list').replaceChildren(...filtered.map(x=>card(x.s,x.m)));let count=filtered.filter(x=>positions.has(x.s.id)).length;el('status').textContent=`전체 ${shops.length}개 중 ${filtered.length}개 업소 · 지도 위치 ${count}개 확인`+(done?` · 전체 위치 미확인 ${failed}개`:key?' · 지도 로딩 중':' · 지도 API 키 필요');if(map){markers.forEach(m=>m.setMap(null));markers=[];let bounds=new kakao.maps.LatLngBounds();for(let x of filtered){let p=positions.get(x.s.id);if(!p)continue;let m=new kakao.maps.Marker({map,position:p,title:x.s.name});kakao.maps.event.addListener(m,'click',()=>show(x.s,x.m));markers.push(m);bounds.extend(p)}if(markers.length&&done)map.setBounds(bounds)}}for(let id of ['q','item','max','sort'])el(id).addEventListener('input',()=>{el('detail').replaceChildren();render()});el('type').onchange=()=>{itemOptions();el('detail').replaceChildren();render()};el('reset').onclick=()=>{for(let id of ['q','type','max'])el(id).value='';itemOptions();el('item').value='';el('sort').value='name';el('detail').replaceChildren();render()};el('loc').onclick=()=>{if(!map||!navigator.geolocation){alert('현재 위치 기능을 사용할 수 없습니다.');return}navigator.geolocation.getCurrentPosition(p=>{map.setCenter(new kakao.maps.LatLng(p.coords.latitude,p.coords.longitude));map.setLevel(4)},()=>alert('위치 권한을 확인해 주세요.'))};render();function init(){map=new kakao.maps.Map(el('map'),{center:new kakao.maps.LatLng(37.5145,127.106),level:7});for(let s of shops){if(Number.isFinite(s.lat)&&Number.isFinite(s.lng)){positions.set(s.id,new kakao.maps.LatLng(s.lat,s.lng))}}done=true;render()}if(key){let script=document.createElement('script');script.src='https://dapi.kakao.com/v2/maps/sdk.js?autoload=false&appkey='+encodeURIComponent(key);script.onload=()=>{if(window.kakao?.maps?.load)kakao.maps.load(init);else el('map').textContent='카카오맵 설정을 확인해 주세요.'};script.onerror=()=>el('map').textContent='지도 로딩 실패: API 키 및 허용 도메인을 확인해 주세요.';document.head.append(script)}else el('map').textContent='카카오맵 JavaScript 키 설정 후 지도 위치가 표시됩니다. 아래 검색은 지금도 가능합니다.';</script></body></html>'''
page=page.replace('__DATA__',data).replace('__KEY__',json.dumps(str(key)).replace('<','\\u003c'))
components.html(page,height=1100,scrolling=True)
